def difference(d1, d2, level=-1):
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        return d1
    if d1 == d2:
        return {}
    elif level == 0:
        return d1
    result = {}
    for key in d1:
        if key not in d2:
            result[key] = d1[key]
        elif d1[key] != d2[key]:
            res = difference(d1[key], d2[key], level-1)
            if res:
                result[key] = res
