def _patch(self, url=None, use_ssl=None, params=None, files=None,
           **kwargs):
    url = self._construct_url(url, use_ssl=use_ssl)
    if not params:
        params = {}
    params = self._construct_payload(params)
    payload = {
        'timeout': self.timeout,
        'headers': params.pop('headers', None)
    }
    if params:
        payload['params'] = params
    if files:
        payload['files'] = files
    if self.auth:
        payload['auth'] = self.auth
    if self.use_json:
        data = kwargs.pop('json', None)
        if data:
            payload['json'] = data
        else:
            payload['json'] = kwargs
    else:
        data = kwargs.pop('data', None)
        if data:
            payload['data'] = data
        else:
            payload['data'] = kwargs
    if 'params' not in payload:
        payload['params'] = {}
    payload['params'].update(**kwargs)
    api_call = requests.patch(url, **payload)
