def match(value, req):
    if req is None:
        if value is None:
            return True
        else:
            return False
    words = req.split()
    op = method = None
    if words:
        op = words.pop(0)
        method = _op_methods.get(op)
    if op != '<or>' and not method:
        return value == req
    if value is None:
        return False
    if op == '<or>':
        while True:
            if words.pop(0) == value:
                return True
            if not words:
                break
            op = words.pop(0)
            if not words:
                break
        return False
    try:
        if words and method(value, words[0]):
            return True
    except ValueError:
        pass
