def parse_desc_file(
    self,
    path: Path,
    repo: str,
    base_url: str,
    dl_url_fmt: str,
) -> Dict[str, Any]:
    rex = re.compile(r"^\%(?P<k>\w+)\%\n(?P<v>.*)\n$", re.M)
    with path.open("rb") as content:
        parsed = rex.findall(content.read().decode())
        data = {entry[0].lower(): entry[1] for entry in parsed}
        if "url" in data.keys():
            data["project_url"] = data["url"]
        assert data["name"]
        assert data["filename"]
        assert data["arch"]
        data["repo"] = repo
        data["url"] = urljoin(
            base_url,
            dl_url_fmt.format(
                base_url=base_url,
                pkgname=data["name"],
                filename=data["filename"],
                arch=data["arch"],
                repo=repo,
            ),
        )
        assert data["md5sum"]
        assert data["sha256sum"]
        data["checksums"] = {
            "md5sum": hash_to_hex(data["md5sum"]),
            "sha256sum": hash_to_hex(data["sha256sum"]),
        }
