def eval(self, graph, subj=None, obj=None, first=True):
    if self.zero and first:
        if subj and obj:
            if subj == obj:
                yield subj, obj
        elif subj:
            yield subj, subj
        elif obj:
            yield obj, obj
    def _fwd(subj=None, obj=None, seen=None):
        seen.add(subj)
        for s, o in evalPath(graph, (subj, self.path, None)):
            if not obj or o == obj:
                yield s, o
            if self.more:
                if o in seen:
                    continue
                for s2, o2 in _fwd(o, obj, seen):
                    yield s, o2
    def _bwd(subj=None, obj=None, seen=None):
        seen.add(obj)
        for s, o in evalPath(graph, (None, self.path, obj)):
            if not subj or subj == s:
                yield s, o
            if self.more:
                if s in seen:
                    continue
                for s2, o2 in _bwd(None, s, seen):
                    yield s2, o
    def _all_fwd_paths():
        if self.zero:
            seen1 = set()
            for s, o in graph.subject_objects(None):
                if s not in seen1:
                    seen1.add(s)
                    yield s, s
                if o not in seen1:
                    seen1.add(o)
                    yield o, o
        seen = set()
        for s, o in evalPath(graph, (None, self.path, None)):
            if not self.more:
                yield s, o
            else:
                if s not in seen:
                    seen.add(s)
                    f = list(_fwd(s, None, set()))
                    for s1, o1 in f:
                        assert s1 == s
                        yield s1, o1
    done = set()
    if subj:
        for x in _fwd(subj, obj, set()):
            if x not in done:
                done.add(x)
                yield x
    elif obj:
        for x in _bwd(subj, obj, set()):
            if x not in done:
                done.add(x)
                yield x
    else:
        for x in _all_fwd_paths():
            if x not in done:
                done.add(x)
